CREATE OR REPLACE MACRO elden_ring.main.attack_poise (cls, weapon_name, atk_name) AS ((SELECT ((sum(h.poise_mv) / 100.0) * w.base_poise_dmg) FROM (elden_ring.main.attack_hits AS h INNER JOIN elden_ring.main.weapon_poise AS w ON (((w."class" = h."class") AND (w.weapon = h.weapon)))) WHERE ((h."class" = cls) AND (h.weapon = weapon_name) AND (h.attack = atk_name)) GROUP BY w.base_poise_dmg));

CREATE OR REPLACE MACRO elden_ring.main.bleed_proc (boss_name, flat) AS ((SELECT ((flat + (0.15 * hp)) * mult_bleed) FROM elden_ring.main.bosses WHERE (boss = boss_name)));

CREATE OR REPLACE MACRO elden_ring.main.blocked_damage (incoming, negation_pct, extra_cut) AS (((incoming * (1 - (negation_pct / 100.0))) * extra_cut));

CREATE OR REPLACE MACRO elden_ring.main.block_stamina_loss (incoming, guard_boost, boost_mult) AS ((incoming * (1 - (least((guard_boost * boost_mult), 100) / 100.0))));

CREATE OR REPLACE MACRO elden_ring.main.boss_hit_damage (atk_by_type, boss_name, phys_kind) AS ((SELECT sum(elden_ring.main.hit_damage(t.atk, b.defense, CASE  WHEN ((t.k = 'physical')) THEN (CASE  WHEN ((phys_kind = 'strike')) THEN (b.neg_strike) WHEN ((phys_kind = 'slash')) THEN (b.neg_slash) WHEN ((phys_kind = 'pierce')) THEN (b.neg_pierce) ELSE b.neg_standard END) WHEN ((t.k = 'magic')) THEN (b.neg_magic) WHEN ((t.k = 'fire')) THEN (b.neg_fire) WHEN ((t.k = 'lightning')) THEN (b.neg_lightning) ELSE b.neg_holy END)) FROM (SELECT unnest(map_keys(atk_by_type)) AS k, unnest(map_values(atk_by_type)) AS atk) AS t , elden_ring.main.bosses AS b WHERE (b.boss = boss_name)));

CREATE OR REPLACE MACRO elden_ring.main.buff_mult (sel, type_name, is_charged, is_2h, is_roar) AS ((SELECT COALESCE(product((1 + (pct / 100.0))), 1) FROM elden_ring.main.buffs WHERE (list_contains(sel, "name") AND (pct != 0) AND ((applies_dmg = 'all') OR list_contains(string_split(applies_dmg, ','), type_name)) AND ((applies_atk = 'any') OR ((applies_atk = 'charged') AND is_charged) OR ((applies_atk = 'two_hand') AND is_2h) OR ((applies_atk = 'roar') AND is_roar)))));

CREATE OR REPLACE MACRO elden_ring.main.buff_poise_mult (sel) AS ((SELECT COALESCE(product((1 + (poise_pct / 100.0))), 1) FROM elden_ring.main.buffs WHERE (list_contains(sel, "name") AND (poise_pct != 0))));

CREATE OR REPLACE MACRO elden_ring.main.buff_stat (sel, attr) AS ((SELECT CAST(COALESCE(sum(CASE  WHEN ((attr = 'str')) THEN (str_bonus) WHEN ((attr = 'dex')) THEN (dex_bonus) WHEN ((attr = 'int')) THEN (int_bonus) WHEN ((attr = 'fai')) THEN (fai_bonus) ELSE arc_bonus END), 0) AS INTEGER) FROM elden_ring.main.buffs WHERE list_contains(sel, "name")));

CREATE OR REPLACE MACRO elden_ring.main.can_buff (p_weapon) AS ((SELECT any_value(buffable) FROM elden_ring.main.weapon_buffable WHERE ("name" = p_weapon)));

CREATE OR REPLACE MACRO elden_ring.main.class_rl (cls, p_vig, p_mnd, p_end, p_str, p_dex, p_int, p_fai, p_arc) AS ((SELECT CASE  WHEN (((p_vig >= c.vig) AND (p_mnd >= c.mnd) AND (p_end >= c.end_) AND (p_str >= c.str) AND (p_dex >= c.dex) AND (p_int >= c."int") AND (p_fai >= c.fai) AND (p_arc >= c.arc))) THEN (((c."level" + (((((((p_vig + p_mnd) + p_end) + p_str) + p_dex) + p_int) + p_fai) + p_arc)) - (((((((c.vig + c.mnd) + c.end_) + c.str) + c.dex) + c."int") + c.fai) + c.arc))) ELSE NULL END FROM elden_ring.main.classes AS c WHERE (c."class" = cls)));

CREATE OR REPLACE MACRO elden_ring.main.defense_mult (atk, def) AS (CASE  WHEN ((def <= 0)) THEN (1.0) WHEN (((atk / def) >= 8)) THEN (0.9) WHEN (((atk / def) >= 2.5)) THEN ((0.9 - (0.2 * pow(((8 - (atk / def)) / 5.5), 2)))) WHEN (((atk / def) >= 1)) THEN ((0.7 - (0.3 * pow(((2.5 - (atk / def)) / 1.5), 2)))) WHEN (((atk / def) >= 0.125)) THEN ((0.1 + (0.3 * pow((((atk / def) - 0.125) / 0.875), 2)))) ELSE 0.1 END);

CREATE OR REPLACE MACRO elden_ring.main.enemy_bleed_proc (enemy_label, flat) AS ((SELECT ((flat + (0.15 * hp)) * mult_bleed) FROM elden_ring.main.enemies WHERE ("label" = enemy_label)));

CREATE OR REPLACE MACRO elden_ring.main.enemy_hit_damage (atk_by_type, enemy_label, phys_kind, blessing) AS ((SELECT (sum(((t.atk * elden_ring.main.defense_mult(t.atk, CASE  WHEN ((t.k = 'physical')) THEN (e.def_phys) WHEN ((t.k = 'magic')) THEN (e.def_magic) WHEN ((t.k = 'fire')) THEN (e.def_fire) WHEN ((t.k = 'lightning')) THEN (e.def_lightning) ELSE e.def_holy END)) * (1 - (CASE  WHEN ((t.k = 'physical')) THEN (CASE  WHEN ((phys_kind = 'strike')) THEN (e.neg_strike) WHEN ((phys_kind = 'slash')) THEN (e.neg_slash) WHEN ((phys_kind = 'pierce')) THEN (e.neg_pierce) ELSE e.neg_standard END) WHEN ((t.k = 'magic')) THEN (e.neg_magic) WHEN ((t.k = 'fire')) THEN (e.neg_fire) WHEN ((t.k = 'lightning')) THEN (e.neg_lightning) ELSE e.neg_holy END / 100.0)))) * (SELECT dmg_mult FROM elden_ring.main.scadutree WHERE ("level" = blessing))) FROM (SELECT unnest(map_keys(atk_by_type)) AS k, unnest(map_values(atk_by_type)) AS atk) AS t , elden_ring.main.enemies AS e WHERE ((e."label" = enemy_label) AND (t.k IN ('physical', 'magic', 'fire', 'lightning', 'holy')))));

CREATE OR REPLACE MACRO elden_ring.main.enemy_threshold (enemy_label, status, n) AS ((SELECT CASE  WHEN ((status = 'bleed')) THEN ((res_bleed + COALESCE(list_sum(res_bleed_adds[1:(n - 1)]), 0))) WHEN ((status = 'frost')) THEN ((res_frost + COALESCE(list_sum(res_frost_adds[1:(n - 1)]), 0))) WHEN ((status = 'poison')) THEN ((res_poison + COALESCE(list_sum(res_poison_adds[1:(n - 1)]), 0))) WHEN ((status = 'rot')) THEN ((res_rot + COALESCE(list_sum(res_rot_adds[1:(n - 1)]), 0))) WHEN ((status = 'sleep')) THEN ((res_sleep + COALESCE(list_sum(res_sleep_adds[1:(n - 1)]), 0))) WHEN ((status = 'madness')) THEN ((res_madness + COALESCE(list_sum(res_madness_adds[1:(n - 1)]), 0))) ELSE NULL END FROM elden_ring.main.enemies WHERE ("label" = enemy_label)));

CREATE OR REPLACE MACRO elden_ring.main.frost_proc (boss_name) AS ((SELECT ((30 + (0.10 * hp)) * mult_frost) FROM elden_ring.main.bosses WHERE (boss = boss_name)));

CREATE OR REPLACE MACRO elden_ring.main.hits_for_procs (enemy_label, status, buildup_per_hit, n) AS ((SELECT CAST(sum(ceil((elden_ring.main.enemy_threshold(enemy_label, status, k) / buildup_per_hit))) AS INTEGER) FROM "range"(1, (n + 1)) AS t(k)));

CREATE OR REPLACE MACRO elden_ring.main.hits_to_stagger (poise_per_hit, boss_name) AS ((SELECT ceil((effective_poise / poise_per_hit)) FROM elden_ring.main.bosses WHERE (boss = boss_name)));

CREATE OR REPLACE MACRO elden_ring.main.hit_damage (atk, def, negation_pct) AS (((atk * elden_ring.main.defense_mult(atk, def)) * (1 - (negation_pct / 100.0))));

CREATE OR REPLACE MACRO elden_ring.main.ar (wname, s, dx, i, f, a, lvl, two_hand) AS TABLE (WITH w AS (SELECT * FROM elden_ring.main.reg_weapons WHERE ("name" = wname) LIMIT 1), L AS (SELECT least(lvl, max_level) AS lv FROM w), st (attr, raw, eff) AS (SELECT * FROM (SELECT * FROM (VALUES ('str', s, CASE  WHEN (((two_hand AND (NOT (SELECT paired FROM w))) OR ((SELECT weapon_type FROM w) IN ('Light Bow', 'Bow', 'Greatbow', 'Ballista')))) THEN (CAST(floor((s * 1.5)) AS INTEGER)) ELSE s END), ('dex', dx, dx), ('int', i, i), ('fai', f, f), ('arc', a, a)) AS valueslist)), req (attr, need) AS (SELECT * FROM (SELECT * FROM (VALUES ('str', (SELECT req_str FROM w)), ('dex', (SELECT req_dex FROM w)), ('int', (SELECT req_int FROM w)), ('fai', (SELECT req_fai FROM w)), ('arc', (SELECT req_arc FROM w))) AS valueslist)), unmet AS (SELECT st.attr FROM (st INNER JOIN req USING (attr)) WHERE (st.eff < req.need)), base AS (SELECT b.type_id, b.base FROM elden_ring.main.reg_base_attack AS b , L WHERE ((b."name" = wname) AND (b.lvl = L.lv))), terms AS (SELECT b.type_id, e.attr, CASE  WHEN ((e.correct IS NULL)) THEN (sc.scaling) ELSE ((e.correct * sc.scaling) / "nullif"(sc0.scaling, 0)) END AS scaling, g."value" AS graph_val FROM ((((((((base AS b INNER JOIN w ON (true)) INNER JOIN elden_ring.main.reg_aec AS e ON (((e.aec_id = w.aec_id) AND (e.type_id = b.type_id)))) INNER JOIN L ON (true)) LEFT JOIN elden_ring.main.reg_scaling AS sc ON (((sc."name" = wname) AND (sc.lvl = L.lv) AND (sc.attr = e.attr)))) LEFT JOIN elden_ring.main.reg_scaling AS sc0 ON (((sc0."name" = wname) AND (sc0.lvl = 0) AND (sc0.attr = e.attr)))) INNER JOIN elden_ring.main.reg_weapon_graph AS wg ON (((wg."name" = wname) AND (wg.type_id = b.type_id)))) INNER JOIN st ON ((st.attr = e.attr))) INNER JOIN elden_ring.main.calc_graph AS g ON (((g.graph_id = wg.graph_id) AND (g.stat = CASE  WHEN ((b.type_id < 5)) THEN (st.eff) ELSE st.raw END))))) SELECT t.type_id, t."type", b.base, CASE  WHEN (EXISTS(SELECT 1 FROM (terms AS x INNER JOIN unmet AS u USING (attr)) WHERE (x.type_id = b.type_id))) THEN ((b.base * 0.6)) ELSE (b.base * (1 + COALESCE((SELECT sum((COALESCE(x.scaling, 0) * x.graph_val)) FROM terms AS x WHERE (x.type_id = b.type_id)), 0))) END AS ar, CASE  WHEN (EXISTS(SELECT 1 FROM (terms AS x INNER JOIN unmet AS u USING (attr)) WHERE (x.type_id = b.type_id))) THEN (true) ELSE false END AS req_unmet FROM (base AS b INNER JOIN elden_ring.main.dmg_types AS t USING (type_id)) ORDER BY t.type_id);

CREATE OR REPLACE MACRO elden_ring.main.ar_all (s, dx, i, f, a, two_hand) AS TABLE (WITH w AS (SELECT *, CASE  WHEN (((two_hand AND (NOT paired)) OR (weapon_type IN ('Light Bow', 'Bow', 'Greatbow', 'Ballista')))) THEN (CAST(floor((s * 1.5)) AS INTEGER)) ELSE s END AS s_eff FROM elden_ring.main.reg_weapons), st AS (SELECT w."name", v.attr, v.raw, v.eff, v.need FROM w , (SELECT * FROM (VALUES ('str', s, w.s_eff, w.req_str), ('dex', dx, dx, w.req_dex), ('int', i, i, w.req_int), ('fai', f, f, w.req_fai), ('arc', a, a, w.req_arc)) AS valueslist) AS v(attr, raw, eff, need)), b AS (SELECT w."name", w.aec_id, w.max_level, ba.type_id, ba.base FROM (w INNER JOIN elden_ring.main.reg_base_attack AS ba ON (((ba."name" = w."name") AND (ba.lvl = w.max_level))))), t AS (SELECT b."name", b.type_id, e.attr, (st.eff < st.need) AS unmet, CASE  WHEN ((e.correct IS NULL)) THEN (sc.scaling) ELSE ((e.correct * sc.scaling) / "nullif"(sc0.scaling, 0)) END AS scaling, g."value" AS gv FROM ((((((b INNER JOIN elden_ring.main.reg_aec AS e ON (((e.aec_id = b.aec_id) AND (e.type_id = b.type_id)))) INNER JOIN st ON (((st."name" = b."name") AND (st.attr = e.attr)))) LEFT JOIN elden_ring.main.reg_scaling AS sc ON (((sc."name" = b."name") AND (sc.lvl = b.max_level) AND (sc.attr = e.attr)))) LEFT JOIN elden_ring.main.reg_scaling AS sc0 ON (((sc0."name" = b."name") AND (sc0.lvl = 0) AND (sc0.attr = e.attr)))) INNER JOIN elden_ring.main.reg_weapon_graph AS wg ON (((wg."name" = b."name") AND (wg.type_id = b.type_id)))) INNER JOIN elden_ring.main.calc_graph AS g ON (((g.graph_id = wg.graph_id) AND (g.stat = CASE  WHEN ((b.type_id < 5)) THEN (st.eff) ELSE st.raw END))))), agg AS (SELECT "name", type_id, bool_or(unmet) AS unmet, sum((COALESCE(scaling, 0) * gv)) AS bonus FROM t GROUP BY ALL) SELECT b."name", b.max_level, b.type_id, d."type", b.base, CASE  WHEN (COALESCE(agg.unmet, false)) THEN ((b.base * 0.6)) ELSE (b.base * (1 + COALESCE(agg.bonus, 0))) END AS ar, COALESCE(agg.unmet, false) AS req_unmet FROM ((b INNER JOIN elden_ring.main.dmg_types AS d USING (type_id)) LEFT JOIN agg USING ("name", type_id)));

CREATE OR REPLACE MACRO elden_ring.main.ashes_for (p_weapon) AS TABLE (SELECT a.ash, a.default_affinity, a.affinities, list_filter(a.affinities, (lambda z: (z IN ('Standard', 'Heavy', 'Keen', 'Quality')))) AS buffable_affinities FROM elden_ring.main.ashes AS a , elden_ring.main.weapon_ash_slot AS x WHERE ((x.weapon = p_weapon) AND x.accepts_ashes AND list_contains(a.weapon_flags, x.mount_flag)) ORDER BY a.ash);

CREATE OR REPLACE MACRO elden_ring.main.ash_fits (p_ash, p_weapon) AS TABLE (WITH a AS (SELECT * FROM elden_ring.main.ashes WHERE (ash = p_ash)), x AS (SELECT * FROM elden_ring.main.weapon_ash_slot WHERE (weapon = p_weapon)) SELECT CASE  WHEN ((((SELECT count_star() FROM a) = 0) OR ((SELECT count_star() FROM x) = 0))) THEN (NULL) WHEN ((NOT (SELECT accepts_ashes FROM x))) THEN (false) WHEN (((SELECT mount_flag FROM x) IS NULL)) THEN (NULL) ELSE list_contains((SELECT weapon_flags FROM a), (SELECT mount_flag FROM x)) END AS ok, CASE  WHEN (((SELECT count_star() FROM a) = 0)) THEN ('unknown Ash of War') WHEN (((SELECT count_star() FROM x) = 0)) THEN ('unknown weapon (use the base name)') WHEN ((NOT (SELECT accepts_ashes FROM x))) THEN ((p_weapon || ' cannot take Ashes of War')) WHEN (((SELECT mount_flag FROM x) IS NULL)) THEN ('DLC weapon type: compatibility not in this data') WHEN (list_contains((SELECT weapon_flags FROM a), (SELECT mount_flag FROM x))) THEN ('ok') ELSE ((p_ash || ' does not fit weapon type ') || (SELECT mount_flag FROM x)) END AS reason, (SELECT affinities FROM a) AS allowed_affinities, list_filter((SELECT affinities FROM a), (lambda z: (z IN ('Standard', 'Heavy', 'Keen', 'Quality')))) AS buffable_affinities);

CREATE OR REPLACE MACRO elden_ring.main.best_class (p_vig, p_mnd, p_end, p_str, p_dex, p_int, p_fai, p_arc) AS TABLE (SELECT k."class", elden_ring.main.class_rl(k."class", p_vig, p_mnd, p_end, p_str, p_dex, p_int, p_fai, p_arc) AS rl FROM elden_ring.main.classes AS k WHERE (elden_ring.main.class_rl(k."class", p_vig, p_mnd, p_end, p_str, p_dex, p_int, p_fai, p_arc) IS NOT NULL) ORDER BY rl, k."class");

CREATE OR REPLACE MACRO elden_ring.main.buffed_mv (wname, s, dx, i, f, a, lvl, two_hand, mv, status_mv, poise_mv, is_charged, is_roar, sel, def, neg) AS TABLE (WITH arr AS (SELECT * FROM elden_ring.main.ar(wname, (s + elden_ring.main.buff_stat(sel, 'str')), (dx + elden_ring.main.buff_stat(sel, 'dex')), (i + elden_ring.main.buff_stat(sel, 'int')), (f + elden_ring.main.buff_stat(sel, 'fai')), (a + elden_ring.main.buff_stat(sel, 'arc')), lvl, two_hand)) SELECT round(sum(CASE  WHEN ((type_id < 5)) THEN (elden_ring.main.hit_damage((((ar * mv) / 100.0) * elden_ring.main.buff_mult(sel, "type", is_charged, two_hand, is_roar)), def, neg)) ELSE NULL END)) AS damage, round(sum(CASE  WHEN ((type_id < 5)) THEN ((((ar * mv) / 100.0) * elden_ring.main.buff_mult(sel, "type", is_charged, two_hand, is_roar))) ELSE NULL END)) AS raw_attack, round(max(CASE  WHEN (("type" = 'bleed')) THEN (((ar * status_mv) / 100.0)) ELSE NULL END)) AS bleed, round(max(CASE  WHEN (("type" = 'frost')) THEN (((ar * status_mv) / 100.0)) ELSE NULL END)) AS frost, round(max(CASE  WHEN (("type" = 'poison')) THEN (((ar * status_mv) / 100.0)) ELSE NULL END)) AS poison, round(max(CASE  WHEN (("type" = 'scarlet_rot')) THEN (((ar * status_mv) / 100.0)) ELSE NULL END)) AS rot, (poise_mv * elden_ring.main.buff_poise_mult(sel)) AS poise_mv_buffed FROM arr);

CREATE OR REPLACE MACRO elden_ring.main.catalyst_scaling (wname, s, dx, i, f, a, lvl) AS TABLE (WITH w AS (SELECT * FROM elden_ring.main.reg_weapons WHERE ("name" = wname) LIMIT 1), L AS (SELECT least(lvl, max_level) AS lv FROM w), st (attr, val) AS (SELECT * FROM (SELECT * FROM (VALUES ('str', s), ('dex', dx), ('int', i), ('fai', f), ('arc', a)) AS valueslist)), req (attr, need) AS (SELECT * FROM (SELECT * FROM (VALUES ('str', (SELECT req_str FROM w)), ('dex', (SELECT req_dex FROM w)), ('int', (SELECT req_int FROM w)), ('fai', (SELECT req_fai FROM w)), ('arc', (SELECT req_arc FROM w))) AS valueslist)), unmet AS (SELECT st.attr FROM (st INNER JOIN req USING (attr)) WHERE (st.val < req.need)), t AS (SELECT d.type_id, d."type", e.attr, CASE  WHEN ((e.correct IS NULL)) THEN (sc.scaling) ELSE ((e.correct * sc.scaling) / "nullif"(sc0.scaling, 0)) END AS scaling, g."value" AS gv FROM ((((((((elden_ring.main.dmg_types AS d INNER JOIN w ON (true)) INNER JOIN L ON (true)) INNER JOIN elden_ring.main.reg_aec AS e ON (((e.aec_id = w.aec_id) AND (e.type_id = d.type_id)))) LEFT JOIN elden_ring.main.reg_scaling AS sc ON (((sc."name" = wname) AND (sc.lvl = L.lv) AND (sc.attr = e.attr)))) LEFT JOIN elden_ring.main.reg_scaling AS sc0 ON (((sc0."name" = wname) AND (sc0.lvl = 0) AND (sc0.attr = e.attr)))) INNER JOIN elden_ring.main.reg_weapon_graph AS wg ON (((wg."name" = wname) AND (wg.type_id = d.type_id)))) INNER JOIN st ON ((st.attr = e.attr))) INNER JOIN elden_ring.main.calc_graph AS g ON (((g.graph_id = wg.graph_id) AND (g.stat = st.val)))) WHERE (d.type_id < 5)) SELECT type_id, "type", CASE  WHEN (bool_or((attr = ANY(SELECT attr FROM unmet)))) THEN (60.0) ELSE (100 * (1 + sum((COALESCE(scaling, 0) * gv)))) END AS spell_scaling FROM t GROUP BY ALL ORDER BY type_id);

CREATE OR REPLACE MACRO elden_ring.main.check_buffs (sel) AS TABLE (WITH s AS (SELECT unnest(sel) AS "name") (SELECT 'unknown buff' AS problem, s."name" AS detail FROM (s LEFT JOIN elden_ring.main.buffs AS b USING ("name")) WHERE (b."name" IS NULL)) UNION ALL (SELECT ('too many in slot ' || b.slot), string_agg(b."name", ', ') FROM ((s INNER JOIN elden_ring.main.buffs AS b USING ("name")) INNER JOIN elden_ring.main.buff_slots AS l USING (slot)) GROUP BY b.slot, l.slot_limit HAVING (count_star() > l.slot_limit))UNION ALL (SELECT (('mutually exclusive (' || b.excl) || ')'), string_agg(b."name", ', ') FROM (s INNER JOIN elden_ring.main.buffs AS b USING ("name")) WHERE (b.excl IS NOT NULL) GROUP BY b.excl HAVING (count_star() > 1)));

CREATE OR REPLACE MACRO elden_ring.main.check_weapon_buff (p_weapon, p_buff, p_hand) AS TABLE (SELECT CASE  WHEN (((SELECT count_star() FROM elden_ring.main.weapon_buffable WHERE ("name" = p_weapon)) = 0)) THEN (false) WHEN (((SELECT count_star() FROM elden_ring.main.weapon_buff_list WHERE (wb_name = p_buff)) = 0)) THEN (false) WHEN ((NOT elden_ring.main.can_buff(p_weapon))) THEN (false) WHEN ((NOT ((SELECT wb_hand FROM elden_ring.main.weapon_buff_list WHERE (wb_name = p_buff)) IN ('either', p_hand)))) THEN (false) ELSE true END AS ok, CASE  WHEN (((SELECT count_star() FROM elden_ring.main.weapon_buffable WHERE ("name" = p_weapon)) = 0)) THEN ('unknown weapon name') WHEN (((SELECT count_star() FROM elden_ring.main.weapon_buff_list WHERE (wb_name = p_buff)) = 0)) THEN ('unknown weapon buff') WHEN ((NOT elden_ring.main.can_buff(p_weapon))) THEN ((((p_weapon || ' cannot be buffed (') || (SELECT CASE  WHEN ((affinity IN ('Standard', 'Heavy', 'Keen', 'Quality'))) THEN ('unique weapon') ELSE (affinity || ' infusion') END FROM elden_ring.main.weapon_buffable WHERE ("name" = p_weapon) LIMIT 1)) || ')')) WHEN ((NOT ((SELECT wb_hand FROM elden_ring.main.weapon_buff_list WHERE (wb_name = p_buff)) IN ('either', p_hand)))) THEN ((((p_buff || ' only works on the ') || (SELECT wb_hand FROM elden_ring.main.weapon_buff_list WHERE (wb_name = p_buff))) || '-hand armament')) ELSE 'ok' END AS reason);

CREATE OR REPLACE MACRO elden_ring.main.enemy_spell_hits (spell_name, catalyst, s, dx, i, f, a, lvl, mult, enemy_label, blessing) AS TABLE (WITH sc AS (SELECT "map"(list("type"), list(spell_scaling)) AS m FROM elden_ring.main.catalyst_scaling(catalyst, s, dx, i, f, a, lvl)) SELECT h.atk_id, h.part, h.charged, round(elden_ring.main.enemy_hit_damage("map"(list_value('physical', 'magic', 'fire', 'lightning', 'holy'), list_value((((h.mv_phys * sc.m['physical']) / 100) * mult), (((h.mv_magic * sc.m['magic']) / 100) * mult), (((h.mv_fire * sc.m['fire']) / 100) * mult), (((h.mv_lightning * sc.m['lightning']) / 100) * mult), (((h.mv_holy * sc.m['holy']) / 100) * mult))), enemy_label, 'standard', blessing), 1) AS damage, b.status, b.buildup FROM ((elden_ring.main.spell_hits AS h CROSS JOIN sc) LEFT JOIN elden_ring.main.spell_buildup(spell_name, catalyst, a, lvl) AS b ON ((b.atk_id = h.atk_id))) WHERE (h.spell = spell_name) ORDER BY h.atk_id);

CREATE OR REPLACE MACRO elden_ring.main.find_enemy (txt) AS TABLE (SELECT "label", hp, def_phys, neg_standard, neg_slash, neg_strike, neg_pierce, neg_fire, neg_holy, res_bleed, res_frost, mult_bleed, stance FROM elden_ring.main.enemies WHERE ("label" ~~* (('%' || txt) || '%')) ORDER BY boss_flag DESC, hp DESC);

CREATE OR REPLACE MACRO elden_ring.main.mv_damage (wname, s, dx, i, f, a, lvl, two_hand, mv, status_mv, mult, def, neg) AS TABLE (SELECT sum(CASE  WHEN ((type_id < 5)) THEN (elden_ring.main.hit_damage((((ar * mv) / 100.0) * mult), def, neg)) ELSE NULL END) AS damage, sum(CASE  WHEN ((type_id < 5)) THEN ((((ar * mv) / 100.0) * mult)) ELSE NULL END) AS raw_attack, max(CASE  WHEN (("type" = 'bleed')) THEN (((ar * status_mv) / 100.0)) ELSE NULL END) AS bleed, max(CASE  WHEN (("type" = 'frost')) THEN (((ar * status_mv) / 100.0)) ELSE NULL END) AS frost, max(CASE  WHEN (("type" = 'poison')) THEN (((ar * status_mv) / 100.0)) ELSE NULL END) AS poison, max(CASE  WHEN (("type" = 'scarlet_rot')) THEN (((ar * status_mv) / 100.0)) ELSE NULL END) AS rot FROM elden_ring.main.ar(wname, s, dx, i, f, a, lvl, two_hand));

CREATE OR REPLACE MACRO elden_ring.main.roll_limits (endur) AS TABLE (SELECT equip_load, round((equip_load * 0.2999), 1) AS light_max, round((equip_load * 0.6999), 1) AS medium_max, equip_load AS heavy_max FROM elden_ring.main.equip_load WHERE (endurance = endur));

CREATE OR REPLACE MACRO elden_ring.main.spell_buildup (spell_name, catalyst, arc, lvl) AS TABLE (SELECT s.atk_id, s.status, s.buildup AS base, CASE  WHEN ((NOT s.arc_scales)) THEN (0) ELSE COALESCE((g."value" * sc.scaling), 0) END AS bonus, round((s.buildup * (1 + CASE  WHEN ((NOT s.arc_scales)) THEN (0) ELSE COALESCE((g."value" * sc.scaling), 0) END)), 1) AS buildup FROM (((elden_ring.main.spell_status AS s LEFT JOIN elden_ring.main.catalyst_status_graph AS cg ON (((cg.catalyst = catalyst) AND (cg.status = s.status)))) LEFT JOIN elden_ring.main.calc_graph AS g ON (((g.graph_id = cg.graph_id) AND (g.stat = arc)))) LEFT JOIN elden_ring.main.reg_scaling AS sc ON (((sc."name" = catalyst) AND (sc.attr = 'arc') AND (sc.lvl = least(lvl, (SELECT max_level FROM elden_ring.main.reg_weapons WHERE ("name" = catalyst) LIMIT 1)))))) WHERE (s.spell = spell_name) ORDER BY s.atk_id);

CREATE OR REPLACE MACRO elden_ring.main.spell_damage (spell_name, catalyst, s, dx, i, f, a, lvl, mult, boss_name) AS TABLE (WITH sc AS (SELECT "map"(list("type"), list(spell_scaling)) AS m FROM elden_ring.main.catalyst_scaling(catalyst, s, dx, i, f, a, lvl)) SELECT h.part, h.atk_id, h.variant, h.charged, h.poise_dmg, COALESCE(o.hits, oa.hits, h.hits_est) AS hits_per_cast, CASE  WHEN (((o.hits IS NOT NULL) OR (oa.hits IS NOT NULL))) THEN ('checked') ELSE h.hit_conf END AS hit_conf, elden_ring.main.boss_hit_damage("map"(list_value('physical', 'magic', 'fire', 'lightning', 'holy'), list_value((((h.mv_phys * sc.m['physical']) / 100) * mult), (((h.mv_magic * sc.m['magic']) / 100) * mult), (((h.mv_fire * sc.m['fire']) / 100) * mult), (((h.mv_lightning * sc.m['lightning']) / 100) * mult), (((h.mv_holy * sc.m['holy']) / 100) * mult))), boss_name, 'standard') AS damage FROM (((elden_ring.main.spell_hits AS h CROSS JOIN sc) LEFT JOIN elden_ring.main.spell_hit_counts AS o ON (((o.spell = h.spell) AND (o.variant = h.variant) AND (o.atk_id = h.atk_id)))) LEFT JOIN elden_ring.main.spell_hit_counts AS oa ON (((oa.spell = h.spell) AND (oa.variant = h.variant) AND (oa.atk_id IS NULL)))) WHERE (h.spell = spell_name) ORDER BY h.variant, h.atk_id);

CREATE OR REPLACE VIEW elden_ring.main.attacks_full AS SELECT a.*, w.is_dlc, f."type", f.startup, f.recovery, f.total, f.cancel_attack, f.cancel_dodge, f.armor_start, f.armor_end, f.first_hit_poise AS poise_effective FROM ((elden_ring.main.attacks AS a LEFT JOIN elden_ring.main.weapons AS w USING ("class", weapon)) LEFT JOIN elden_ring.main.frames AS f ON (((f."class" = a."class") AND (f.weapon = a.weapon) AND (f.attack = a.attack))));

CREATE OR REPLACE VIEW elden_ring.main.mv_weapon_bridge AS (SELECT DISTINCT w."class", w.weapon, r.base_weapon, false AS is_proxy FROM (elden_ring.main.weapons AS w INNER JOIN (SELECT DISTINCT base_weapon FROM elden_ring.main.reg_weapons) AS r ON ((lower("replace"(r.base_weapon, '’', '''')) = lower("replace"(w.weapon, '’', '''')))))) UNION ALL (SELECT p."class", p.proxy_weapon, p.new_weapon, true FROM elden_ring.main.moveset_proxies AS p);

CREATE OR REPLACE MACRO elden_ring.main.ar_total (wname, s, dx, i, f, a, lvl, two_hand) AS ((SELECT sum(floor(ar)) FROM elden_ring.main.ar(wname, s, dx, i, f, a, lvl, two_hand) WHERE (type_id < 5)));

CREATE OR REPLACE MACRO elden_ring.main.boss_mv_damage (wname, s, dx, i, f, a, lvl, two_hand, mv, is_charged, is_roar, sel, boss_name, phys_kind) AS ((WITH arr AS (SELECT * FROM elden_ring.main.ar(wname, (s + elden_ring.main.buff_stat(sel, 'str')), (dx + elden_ring.main.buff_stat(sel, 'dex')), (i + elden_ring.main.buff_stat(sel, 'int')), (f + elden_ring.main.buff_stat(sel, 'fai')), (a + elden_ring.main.buff_stat(sel, 'arc')), lvl, two_hand) WHERE (type_id < 5)) SELECT elden_ring.main.boss_hit_damage("map"(list("type"), list((((ar * mv) / 100.0) * elden_ring.main.buff_mult(sel, "type", is_charged, two_hand, is_roar)))), boss_name, phys_kind) FROM arr));

CREATE OR REPLACE MACRO elden_ring.main.attack_damage (wname, s, dx, i, f, a, lvl, two_hand, atk_name, mult, def, neg) AS TABLE (WITH arr AS (SELECT * FROM elden_ring.main.ar(wname, s, dx, i, f, a, lvl, two_hand)), mvw AS (SELECT b."class", b.weapon FROM (elden_ring.main.mv_weapon_bridge AS b INNER JOIN elden_ring.main.reg_weapons AS r ON ((r.base_weapon = b.base_weapon))) WHERE (r."name" = wname) LIMIT 1), hits AS (SELECT h.* FROM (elden_ring.main.attack_hits AS h INNER JOIN mvw ON (((h."class" = mvw."class") AND (h.weapon = mvw.weapon)))) WHERE (h.attack = atk_name)) SELECT h.hit, h.mv, h.status_mv, h.poise_mv, sum(CASE  WHEN ((arr.type_id < 5)) THEN (elden_ring.main.hit_damage((((arr.ar * h.mv) / 100.0) * mult), def, neg)) ELSE NULL END) AS damage, sum(CASE  WHEN ((arr.type_id < 5)) THEN ((((arr.ar * h.mv) / 100.0) * mult)) ELSE NULL END) AS raw_attack, max(CASE  WHEN ((arr."type" = 'bleed')) THEN (((arr.ar * h.status_mv) / 100.0)) ELSE NULL END) AS bleed, max(CASE  WHEN ((arr."type" = 'frost')) THEN (((arr.ar * h.status_mv) / 100.0)) ELSE NULL END) AS frost, max(CASE  WHEN ((arr."type" = 'poison')) THEN (((arr.ar * h.status_mv) / 100.0)) ELSE NULL END) AS poison, max(CASE  WHEN ((arr."type" = 'scarlet_rot')) THEN (((arr.ar * h.status_mv) / 100.0)) ELSE NULL END) AS rot, max(CASE  WHEN ((arr."type" = 'sleep')) THEN (((arr.ar * h.status_mv) / 100.0)) ELSE NULL END) AS sleep, max(CASE  WHEN ((arr."type" = 'madness')) THEN (((arr.ar * h.status_mv) / 100.0)) ELSE NULL END) AS madness FROM hits AS h , arr GROUP BY ALL ORDER BY h.hit);

CREATE OR REPLACE MACRO elden_ring.main.buffed_attack (wname, s, dx, i, f, a, lvl, two_hand, atk_name, sel, def, neg) AS TABLE (WITH mvw AS (SELECT b."class", b.weapon FROM (elden_ring.main.mv_weapon_bridge AS b INNER JOIN elden_ring.main.reg_weapons AS r ON ((r.base_weapon = b.base_weapon))) WHERE (r."name" = wname) LIMIT 1), hits AS (SELECT h.* FROM (elden_ring.main.attack_hits AS h INNER JOIN mvw ON (((h."class" = mvw."class") AND (h.weapon = mvw.weapon)))) WHERE (h.attack = atk_name)), arr AS (SELECT * FROM elden_ring.main.ar(wname, (s + elden_ring.main.buff_stat(sel, 'str')), (dx + elden_ring.main.buff_stat(sel, 'dex')), (i + elden_ring.main.buff_stat(sel, 'int')), (f + elden_ring.main.buff_stat(sel, 'fai')), (a + elden_ring.main.buff_stat(sel, 'arc')), lvl, two_hand)), ph AS (SELECT h.hit, h.poise_mv, sum(CASE  WHEN ((arr.type_id < 5)) THEN (elden_ring.main.hit_damage((((arr.ar * h.mv) / 100.0) * elden_ring.main.buff_mult(sel, arr."type", (atk_name ~~* '%charged%'), two_hand, false)), def, neg)) ELSE NULL END) AS dmg, max(CASE  WHEN ((arr."type" = 'bleed')) THEN (((arr.ar * h.status_mv) / 100)) ELSE NULL END) AS bleed, max(CASE  WHEN ((arr."type" = 'frost')) THEN (((arr.ar * h.status_mv) / 100)) ELSE NULL END) AS frost, max(CASE  WHEN ((arr."type" = 'poison')) THEN (((arr.ar * h.status_mv) / 100)) ELSE NULL END) AS poison, max(CASE  WHEN ((arr."type" = 'scarlet_rot')) THEN (((arr.ar * h.status_mv) / 100)) ELSE NULL END) AS rot FROM hits AS h , arr GROUP BY ALL) SELECT count_star() AS hits, round(sum(dmg)) AS damage, round(sum(bleed)) AS bleed, round(sum(frost)) AS frost, round(sum(poison)) AS poison, round(sum(rot)) AS rot, (sum(poise_mv) * elden_ring.main.buff_poise_mult(sel)) AS poise_mv_buffed FROM ph);

CREATE OR REPLACE MACRO elden_ring.main.rank_attack (atk_name, s, dx, i, f, a, two_hand, mult, def, neg) AS TABLE (WITH arw AS (SELECT * FROM elden_ring.main.ar_all(s, dx, i, f, a, two_hand)), h AS (SELECT r."name", br."class", h.hit, h.mv, h.status_mv, h.poise_mv FROM ((elden_ring.main.reg_weapons AS r INNER JOIN elden_ring.main.mv_weapon_bridge AS br ON ((br.base_weapon = r.base_weapon))) INNER JOIN elden_ring.main.attack_hits AS h ON (((h."class" = br."class") AND (h.weapon = br.weapon) AND (h.attack = atk_name))))), per_hit AS (SELECT h."name", h."class", h.hit, h.mv, h.status_mv, h.poise_mv, sum(CASE  WHEN ((arw.type_id < 5)) THEN (elden_ring.main.hit_damage((((arw.ar * h.mv) / 100.0) * mult), def, neg)) ELSE NULL END) AS dmg, sum(CASE  WHEN ((arw.type_id < 5)) THEN ((((arw.ar * h.mv) / 100.0) * mult)) ELSE NULL END) AS raw_atk, max(CASE  WHEN ((arw."type" = 'bleed')) THEN (((arw.ar * h.status_mv) / 100)) ELSE NULL END) AS bleed, max(CASE  WHEN ((arw."type" = 'frost')) THEN (((arw.ar * h.status_mv) / 100)) ELSE NULL END) AS frost, max(CASE  WHEN ((arw."type" = 'poison')) THEN (((arw.ar * h.status_mv) / 100)) ELSE NULL END) AS poison, max(CASE  WHEN ((arw."type" = 'scarlet_rot')) THEN (((arw.ar * h.status_mv) / 100)) ELSE NULL END) AS rot, bool_or(arw.req_unmet) AS req_unmet FROM (h INNER JOIN arw ON ((arw."name" = h."name"))) GROUP BY ALL) SELECT p."name", r.affinity, r.weapon_type, r.is_dlc, count_star() AS hits, round(sum(dmg)) AS damage, round(sum(raw_atk)) AS raw_attack, round(sum(bleed), 1) AS bleed, round(sum(frost), 1) AS frost, round(sum(poison), 1) AS poison, round(sum(rot), 1) AS rot, sum(p.poise_mv) AS poise_mv, bool_or(req_unmet) AS req_unmet, (SELECT sum(floor(ar)) FROM arw AS x WHERE ((x."name" = p."name") AND (x.type_id < 5))) AS ar_total FROM (per_hit AS p INNER JOIN elden_ring.main.reg_weapons AS r ON ((r."name" = p."name"))) GROUP BY ALL);

CREATE OR REPLACE MACRO elden_ring.main.spell_cast_damage (spell_name, catalyst, s, dx, i, f, a, lvl, mult, boss_name, var) AS TABLE (SELECT var AS variant, max(damage) AS max_hit, sum((damage * hits_per_cast)) AS per_cast, bool_or((hits_per_cast IS NULL)) AS has_repeat_hits, string_agg(DISTINCT hit_conf, ',') AS hit_conf FROM elden_ring.main.spell_damage(spell_name, catalyst, s, dx, i, f, a, lvl, mult, boss_name) WHERE (variant = var));
